"""Render the final report from completed native evidence, never execute a model."""
from analyze import *

def main():
    a=read(ROOT/'analysis.json');d=read(ROOT/'DETAILS.json');acct=read(ROOT/'FINAL_ACCOUNTING.json');policy=read(ROOT/'COMMON_POLICY.json');panel=read(ROOT/'common-panel.json');sens=read(ROOT/'SENSITIVITY_REPORT.json');gate=read(ROOT/'COMMON_BLIND_GATE.json')
    assert a['retained_all_slots']==1024 and d['total_reserved']<=2048
    aligned=read(ROOT/'ALIGNED_QUALIFICATION.json');assert len(aligned)==32 and all(all(v for k,v in x.items() if k.endswith('equal')) for x in aligned)
    best=d['break_even']['fastest_fixed_by_geomean'];primary=next(x for x in a['contrasts'] if x['baseline']==best)
    title='Registered AUTO service benefit' if a['engineering_screen_pass'] else 'No registered useful AUTO service benefit'
    lines=[f'# RTX natural prefix reuse: {title}', '', f"All32 held-out roots and all4 arms passed native qualification. All512 formal measurements and512 immediate warmups completed once across four independently loaded sessions. The registered engineering screen is **{'PASS' if a['engineering_screen_pass'] else 'NOT MET'}**. AUTO was frozen to `{policy['global_fixed_arm']}` for every structural bin. Against the fastest fixed arm (`{best}`), its point service-time reduction is {primary['time_reduction_pct']:.4f}%; the baseline/AUTO family-adjusted interval is [{primary['family95_bonferroni_interval'][0]:.6f}, {primary['family95_bonferroni_interval'][1]:.6f}].", '', 'This is one exact-token file-backed replay deployment on the original RTX5070 Ti Laptop host. It is not a production throughput, task-quality, GPU-population or cross-platform pooled estimate. A non-passing usefulness screen is not an equivalence result.', '', '## Execution and frozen identity', '', '- Design PR172 actual starting head: `801196166c8e2a02215003301d129e68504e6b72`; result branch: `codex/rtx-prefix-reuse-results`.', '- Scientific ancestor PR171: `371223b696bb805030c29f04e39eb17b57fb2ebb`. Original scalar reference libraries and the unchanged packed CUDA arithmetic shared by all candidate arms remain authenticated.', '- RTX source/policy freeze: `efd92438a08a4e9c37a422731ddd6850d8907f1b`; B570 actual freeze: `6517c79b59ad3d813a35fa087d15751b825dad34`.', f"- Joint gate released at `{gate['utc']}` after independent44-row identity/token/physical-head verification, before local held-out outputs. See [gate](evidence/COMMON_BLIND_GATE.json).", '- Qwen3-8B Q8_0 SHA256 `408b955510e196121c1c375201744783b5c9a43c7956d73fc78df54c66e883d6`; C4096, F16 KV, non-flash, qmax32, target-only, all GPU, greedy cap128/native EOG.', '- Native tokenizer identity `cc2cca16f808de7d17ae597b6f70563c006ff70d9a0dfae84ab5ccbd518e96ee`; template `57f1fd00f0013a2be96aa79b857391f27e23df5b5f847072b524c897e24d0361`.', '', 'A model and context stay resident within each session. Complete service includes snapshot file read, prefix-index materialization, reset, lookup/import, one policy lookup, append, greedy continuation, synchronization and owned response commit. Shared model/context startup and evidence serialization are outside service and retained in process accounting. B570 uses host-memory snapshots, so matched inputs do not justify a pure hardware timing contrast.', '', '## Natural opportunity and fixed cohorts', '', 'The pinned OASST1 leaf pool has6,423 eligible paths from2,596 roots. Complete history and request strings were rendered and tokenized natively; token-level LCP, real allocator metadata and actual restored dense heads were checked. No synthetic padding, offset selection or prompt truncation was used. The earlier broader-path interpretation and its costs/reference bytes remain as engineering evidence; it contributed no exposed root to the common held-out panel.', '', '| Granule | Eligible paths | Lost reuse | Crossed paths | Crossed q32 calls / total | Test crossed / eligible |', '|---:|---:|---:|---:|---:|---:|']
    for x in sens['scenarios']:lines.append(f"| {x['granule']} | {x['eligible_paths']} | {x['lost_reuse_paths']} | {x['crossed_paths']} | {x['crossed_qb_calls']} / {x['qb_calls']} | {x['test']['crossed_paths']} / {x['test']['eligible_paths']} |")
    lines += ['', 'Granule1 is the implemented deployment. Granules16/32/64 are predeclared output-free floor-LCP scenarios from the original descriptors, not measured engine configurations. They use the same fixed panel without re-ranking. q32-aligned heads remove internal crossings; this does not establish that every serving engine uses those heads. The actual deployment retains573 crossed paths (623/9,888 q32 calls,6.30%); the12 calibration roots contain zero crossings and the32 held-out roots contain four.', '', '## Native qualification', '', '- Original scalar reference: two independent runs for each of32 held-out roots.', '- Main qualification: all160 original-repeat/candidate comparisons passed complete binary32 vocabulary vectors, endpoints, positions and final sequence-state bytes; all256 candidate heavy/off slots completed. Actual plans and physical heads matched the declared policies.', '- Separate continuous-scalar/restore and own-prefix candidate diagnostics matched75 full vectors and final state per comparison. Extra known-append rows use separate output flags and do not replace real-service qualification.', '- Empty-cache control: first8 unchanged full prompts; all32 reference-repeat/fixed-arm comparisons passed, with64 qualification and96 timed/warm slots.', '- All1024 main service outputs and positions were checked against immutable original references during reconstruction. No passing subset was selected.', '', 'See [main proof](evidence/MAIN_QUALIFICATION.json), [aligned proof](evidence/ALIGNED_QUALIFICATION.json), and [raw archive verification](evidence/raw-evidence.zip.RESTORED_DOWNLOAD.json).', '', '## Complete-service results', '', 'Ratios are fixed baseline time / AUTO time; values above1 favor AUTO. Roots are equally weighted, retaining all four paired session vectors. Intervals use10,000 root-bootstrap draws, seed20261104; each primary interval is two-sided98.333% (Bonferroni family95% across three comparisons).', '', '| Baseline | Baseline / AUTO | AUTO reduction % | Family-adjusted interval | Session ratios 1–4 |', '|---|---:|---:|---|---|']
    for x in a['contrasts']:lines.append(f"| {x['baseline']} | {x['baseline_over_AUTO']:.6f} | {x['time_reduction_pct']:.4f} | [{x['family95_bonferroni_interval'][0]:.6f}, {x['family95_bonferroni_interval'][1]:.6f}] | {', '.join(f'{v:.6f}' for v in x['session_ratios'])} |")
    lines += ['', 'The engineering criterion requires every family interval above1 and at least3% reduction versus the fastest fixed arm. All four sessions occurred on2026-11-04; there is no cross-date inference. Secondary unadjusted intervals, all root contrasts and worst regressions remain in [analysis](evidence/analysis.json).', '', '| Arm | Geometric service s | Mean service s | Median s | Descriptive p95 s |', '|---|---:|---:|---:|---:|']
    for arm in study.ARMS:
        x=acct['costs'][arm];lines.append(f"| {arm} | {x['geomean_seconds']:.6f} | {x['arithmetic_mean_seconds']:.6f} | {x['median_seconds']:.6f} | {x['descriptive_p95_seconds']:.6f} |")
    lines += ['', 'These percentiles describe128 measurements per arm conditional on32 roots and four sessions; they are not an SLA estimate.', '', 'Descriptive fixed-policy comparisons (no additional hypothesis tests):']
    for x in d['fixed_service_contrasts']:lines.append(f"- {x['numerator']} / {x['denominator']}: {x['geometric_ratio']:.6f}; session ratios {', '.join(f'{v:.6f}' for v in x['session_ratios'])}.")
    lines += ['', '## Append, imports and aligned control', '', '| Arm | Geometric receipt-to-append s | Mean cumulative import s | Mean snapshot bytes | Empty-cache geometric service s |', '|---|---:|---:|---:|---:|']
    for arm in study.ARMS:
        x=d['phase_summaries'][arm];control=d['aligned_control'].get(arm);last=f"{control['geomean_service_seconds']:.6f}" if control else 'not scheduled';lines.append(f"| {arm} | {x['append_from_receipt_s']['geomean']:.6f} | {x['import_s']['mean']:.6f} | {x['state_bytes']['mean']:.0f} | {last} |")
    lines += ['', d['phase_semantics'], 'The empty-cache control uses another workload lifecycle and is not pooled with cache-hit service. Existing CUDA graph reuse log events are retained by process; no complete hit-rate denominator or per-arm kernel mask/join attribution is claimed.', '', '## Complete costs and retained failures', '', f"- Calibration campaign elapsed: **{acct['calibration']:.6f}s**, including earlier repair/cohort epochs and idle coordination inside the recorded calibration window. The window starts with the first original calibration request; initial setup/build time before it is outside this explicitly named calibration window.", f"- Conservative request reservations: **{d['total_reserved']} /2048**; completed native request receipts: **{d['total_completed']}**; reserved units without a completed receipt: **{d['total_reserved_without_receipt']}**. Interrupted batches retain their entire reservation.", f"- Zero-forward launches: **{acct['zero_forward_started']}**; completed native process wall sum: **{acct['native_wall_seconds']:.6f}s** (separate from, not added to, overlapping calibration wall time).", f"- Main measured service sum: **{acct['main_measure_seconds']:.6f}s**; immediate-warmup service sum: **{acct['main_warmup_seconds']:.6f}s**.", f"- Main observed cache-hit fraction:100%; serialized snapshot bytes supplied to the import API totaled **{d['observed_trace']['main_import_bytes']} bytes** across1024 main slots. These are serialized API input bytes, not measured PCIe traffic. The planned replay hit fraction is not a production traffic estimate.", f"- Across all completed engineering/calibration/main/control requests, recorded service windows sum to **{d['observed_trace']['completed_service_seconds']:.6f}s**; disjoint positive-head prefix production adds **{d['observed_trace']['completed_prefix_producer_seconds']:.6f}s**. Heavy-observer I/O is included where actually used. Model-load windows sum to **{d['observed_trace']['all_completed_model_load_seconds']:.6f}s** and remain separately reported.", '- The pre-freeze epoch omitting file/index costs was interrupted and invalidated for service claims. A later batch was interrupted for output-blind leaf-cohort reconciliation. Both batches, incomplete slots, original references, source epochs and cumulative costs remain in the raw archive and ledger; no favorable rerun was selected.', '', 'The full slot-by-slot disposition and process exits are in [details](evidence/DETAILS.json) and [accounting](evidence/FINAL_ACCOUNTING.json). Compile command outcomes/logs and old historical evidence remain separately pinned; no old R is replaced.']
    be=d['break_even'];lines += ['', f"AUTO arithmetic mean service saving versus `{best}` is {be['mean_service_saving_seconds']:.9f}s/request; the secondary descriptive paired-root95% interval is [{be['secondary_paired_root95_saving_interval'][0]:.9f}, {be['secondary_paired_root95_saving_interval'][1]:.9f}]. This is a post-selection descriptive calculation, not another primary significance test.", (f"Point calibration break-even is {be['point_requests']:.1f} requests." if be['point_requests'] is not None else 'No positive point saving exists, so no finite point calibration break-even is reported.'), (f"The corresponding positive-saving interval implies {be['interval_requests'][0]:.1f}–{be['interval_requests'][1]:.1f} requests." if be['interval_requests'] else 'The saving interval includes nonpositive values, so a finite uncertainty-bounded break-even is not established.'), 'Only128 AUTO measurements were observed, four per root. No unlimited reuse/fanout is assumed.', '', '## Reproduction and delivery', '', 'Release: [rtx-prefix-reuse-v1-20261104](https://github.com/leecdiang/HeteroSpec/releases/tag/rtx-prefix-reuse-v1-20261104). It contains the frozen runtime, complete native source kit, pre-test calibration archive and final raw evidence parts with whole/part SHA256 manifests. Model weights are excluded and must match the pinned hash.', '', 'Follow [execution README](README.md). `download_parts.py` downloads to a fresh directory, authenticates and joins parts, and reconstructs raw qualification and bootstrap results. `reproduce.py --prepare-only` checks the delivered runtime/model and rebases immutable snapshot paths without adding native measurements. Actual replay is a new run and must be charged separately. The worker deliberately requires an NVIDIA device description containing5070; another deployment needs new qualification.', '', 'Actual restored-download verification is documented separately from local packaging checks. Neither is third-party native replication. No result was merged and no manuscript was changed.', '', '## All held-out root contrasts', '', '| Input ID | QB / AUTO | WB-cut / AUTO | WB-rechunk / AUTO |', '|---|---:|---:|---:|']
    for x in a['root_results']:lines.append('| '+x['id']+' | '+' | '.join(f"{x['baseline_over_AUTO'][arm]:.6f}" for arm in study.FIXED)+' |')
    if (ROOT/'DELIVERY.json').exists():
        delivered=read(ROOT/'DELIVERY.json');assert delivered['status']=='NATIVE_STUDY_AND_RESTORED_DELIVERY_COMPLETE'
        at=lines.index('## All held-out root contrasts')
        lines[at:at]=['## Delivered verification','', 'All 58 final raw parts were downloaded from GitHub, authenticated and rejoined. The downloaded archive reconstructed all qualification evidence, 144 calibration slots, 1024 main slots, 96 aligned slots, separate restore diagnostics and the exact bootstrap result. It retains 56,588 original paths and 8,988 unique content blobs. Whole-archive SHA256: `5850cd9e839f099c6105ae54ce144494d32ee6e058b32cb3701e8f2272de5570`.', '', 'Prepare-only replay also passed against the downloaded runtime/raw archives and exact model, materializing 32 authenticated snapshots for the original main-session manifest. It added zero model requests. [Delivery receipt](evidence/DELIVERY.json) retains transfer retries and verification scope; this is not third-party native replication.','']
    import re
    text='\n'.join(lines)+'\n'
    text=re.sub(r'\b(All|all|and|independent|has|from|retains|the|of|matched|first|with|above|use|seed|sided|family|least|on|describe|Only|containing|across|Granule|Granules|RTX)(?=\d)',r'\1 ',text)
    text=text.replace('comparisons (no additional hypothesis tests):\n-','comparisons (no additional hypothesis tests):\n\n-').replace('fraction:100%','fraction: 100%').replace(' /2048',' / 2048').replace('calls,6.30%','calls, 6.30%')
    (HERE/'RESULTS.md').write_text(text,encoding='utf8')
    print(title)
if __name__=='__main__':main()
